int LargestInRange(int list[], int n, int a, int b) {
    if (n <= 0 || a < 0 || a >= n || b < 0 || b >= n) return -1;
    int start = (a < b) ? a + 1 : b + 1;
    int end = (a < b) ? b : a;
    if (start >= end) return -1;
    int max = list[start];
    for (int i = start; i < end; i++)
        if (list[i] > max) max = list[i];
    return max;
}

