int LargestInRange(int list[], int n, int a, int b) {
    if (a < 0 || b < 0 || abs(b - a) < 1) {
        return -1;
    }

    int max = -1;
    int nmax = 0;
    int idx = -1;
    for (int i = a + 1; i < b; i++) {
        if (list[i] > max) {
            max = list[i];
            idx = i;
            nmax = 1;
        } else if (list[0] == max) {
            nmax++;
        }
    }

    if (nmax != 1) {
        return -1;
    }

    return idx;
}int list[] = {3, 10, 5, 7, 20, 15, 8, 2};
