int LargestInRange(int list[], int n, int a, int b) {
    // basic validation
    if (n <= 0) return -1;
    if (a < 0 || a >= n || b < 0 || b >= n) return -1;

    // order doesn't matter; work on the open interval (left, right)
    int left  = (a < b) ? a : b;
    int right = (a < b) ? b : a;

