int LargestInRange(int list[], int n, int a, int b) 
{
	if (a < 0 || b >= n || a > b) {
		return -1;
	}

	int maxIndex = a;
	for (int i = a + 1; i <= b; i++) {
		if (list[i] > list[maxIndex]) {
			maxIndex = i;
		}
	}

	return maxIndex;
}
