int LargestInRange(int list[], int n, int a, int b) {
    // Check bounds
    if (a < 0 || b < 0 || a >= n || b >= n) {
        return -1;
    }

    // Ensure a <= b
    if (a > b) {
        int temp = a;
        a = b;
        b = temp;
    }

    // Check distance (must be at least 1)
    if ((b - a) < 1) {
        return -1;
    }

    int maxIndex = a;
    for (int i = a + 1; i <= b; i++) {
        if (list[i] > list[maxIndex]) {
            maxIndex = i;
        }
    }

    return maxIndex;
}

