int LargestInRanged(int list[], int n, int a, int b) {
    // Check for invalid range or too small range after ignoring first and last
    if ((a >= n) || (b >= n) || ((b - a) <= 1)) {
        return -1;
    }

    int maxIndex = a + 1; // start after first element
    int i;

    // loop through indices after ignoring first and last
    for (i = a + 1; i < b; i++) {
        if (list[i] > list[maxIndex]) {
            maxIndex = i;
        }
    }

    return maxIndex;
}
