int LargestInRange(int list[], int n, int a, int b) 
{
	if (a > b) {
		int temp = a;
		a = b;
		b = temp;
	}
	int max = list[a];
	for (int i = a + 1; i <= b; i++) {
		if (list[i] > max) {
			max = list[i];
		}
	}
	return max;
}

