int LargestInRange(int list[], int n, int a, int b) {
    // First, make sure a and b are within valid bounds (0 to n-1)
    if (a < 0) a = 0;
    if (b >= n) b = n - 1;
    if (a > b) return 0; // Invalid range

    int max = list[a]; // Start with the first element in the range

    // Check each element from position a to b
    for (int i = a + 1; i <= b; i++) {
        if (list[i] > max) {
            max = list[i];
        }
    }

    return max;
}

