int LargestInRange(int list[], int n, int a, int b) {
    // Ensure a <= b
    if (a > b) {
        int temp = a;
        a = b;
        b = temp;
    }

    int max = -1;  // Assume no valid element exists, or we can initialize with a lower bound if required

    // Iterate over the array and find the largest element within the range [a, b]
    for (int i = 0; i < n; i++) {
        if (list[i] >= a && list[i] <= b) {
            if (max == -1 || list[i] > max) {
                max = list[i];
            }
        }
    }

    return max;
}

int main() {
    int arr[] = {1, 5, 3, 8, 2, 9, 6};
    int n = sizeof(arr) / sizeof(arr[0]);
    int a = 3, b = 8;

    int result = LargestInRange(arr, n, a, b);

    if (result != -1) {
        printf("The largest element in the range [%d, %d] is %d\n", a, b, result);
    } else {
        printf("No element found in the range [%d, %d]\n", a, b);
    }

    return 0;
}

