#include <limits.h>

int LargestInRange(int list[], int n, int a, int b) {
    // Basic validation
    if (n <= 0) return -1;
    if (a < 0 || a >= n || b < 0 || b >= n) return -1;

    // Ensure a < b by swapping if needed
    if (a > b) {
        int tmp = a; a = b; b = tmp;
    }

    // Exclusive range (a, b) => indices a+1 ... b-1
    int start = a + 1;
    int end   = b - 1;

    // Empty range
    if (start > end) return -1;

    // Find maximum value's FIRST occurrence in the range
    int bestIdx = -1;
    int bestVal = INT_MIN;

    for (int i = start; i <= end; i++) {
        if (list[i] > bestVal) {
            bestVal = list[i];
            bestIdx = i;      // first occurrence kept naturally
        }
    }

    return bestIdx;  // -1 only if the range was empty
}

